int i = 0, j = 10;

// Loop continues as long as i's pre-incremented value is less than j's
// value *before* j is decremented (postfix).
// i is immediately updated; j update occurs after the comparison value is used.
while (++i < j--) {
    // i: 1, 2, 3, 4, 5
    // j_used: 10, 9, 8, 7, 6
    // j_actual: 9, 8, 7, 6, 5

    if (i == 5) {
        // Condition: ++i (6) < j-- (5) -> 6 < 5 (False)
        break; 
    }
}
// Final i = 5
// Final j = 5
// Total 5 iterations.
